export type ChannelEvent={ticketId:number;text:string};export type Connection={on:(listener:(event:ChannelEvent)=>void)=>()=>void;close:()=>void};export type Connect=(ticketId:number)=>Connection;
export async function playSafely(play:()=>Promise<void>,onError:()=>void):Promise<void>{try{await play();}catch{onError();}}
export type Rect={top:number;bottom:number;left:number};export function placeTooltip(anchor:Rect,width:number,height:number,viewportWidth:number,viewportHeight:number){const gap=8,padding=8;const above=anchor.top-height-gap;const candidate=above>=padding?above:anchor.bottom+gap;return {top:Math.max(padding,Math.min(candidate,Math.max(padding,viewportHeight-height-padding))),left:Math.max(padding,Math.min(anchor.left,Math.max(padding,viewportWidth-width-padding))),placement:above>=padding?"above" as const:"below" as const};}

